description:
A debug tool sometimes changes a setting for a moment, for example making the game run at quarter speed while a single frame is examined, and must always put it back, however the function exits.

Write the RAII class `ScopedValue`. Its constructor receives a reference to an `int` and a temporary value. It remembers the old value and sets the `int` to the temporary one. Its destructor puts the old value back.

```cpp
int speed{ 100 };
{
    ScopedValue slow{ speed, 25 };
    // speed is 25 here
}
// speed is 100 again
```

Copying a `ScopedValue` would restore the value twice, so delete the copy constructor and copy assignment.

starter.solution.cpp:
// Sets target to temporary for as long as this object lives, then restores the old value.
class ScopedValue
{
public:
    ScopedValue(int& target, int temporary)
        : m_target{ target }, m_old{ target }
    {
    }

private:
    int& m_target;
    int m_old;
};

solution.solution.cpp:
// Sets target to temporary for as long as this object lives, then restores the old value.
class ScopedValue
{
public:
    ScopedValue(int& target, int temporary)
        : m_target{ target }, m_old{ target }
    {
        m_target = temporary;
    }

    ~ScopedValue() { m_target = m_old; }

    ScopedValue(const ScopedValue&) = delete;
    ScopedValue& operator=(const ScopedValue&) = delete;

private:
    int& m_target;
    int m_old;
};

unitTests:
#include <stdexcept>
#include <type_traits>
TEST("set while alive, restored after")
{
    int speed{ 100 };
    {
        ScopedValue slow{ speed, 25 };
        CHECK_EQ(speed, 25);
    }
    CHECK_EQ(speed, 100);
}
TEST("nested scopes restore in order")
{
    int volume{ 10 };
    {
        ScopedValue a{ volume, 5 };
        {
            ScopedValue b{ volume, 0 };
            CHECK_EQ(volume, 0);
        }
        CHECK_EQ(volume, 5);
    }
    CHECK_EQ(volume, 10);
}
TEST("restored when an exception passes through")
{
    int lives{ 3 };
    try
    {
        ScopedValue god{ lives, 999 };
        throw std::runtime_error{ "boom" };
    }
    catch (const std::exception&) {}
    CHECK_EQ(lives, 3);
}
TEST("cannot be copied")
{
    CHECK(!std::is_copy_constructible_v<ScopedValue>);
    CHECK(!std::is_copy_assignable_v<ScopedValue>);
}

